import { generateKeyPairSync } from 'node:crypto';
import { buildManifest, signManifest, canonicalJSON } from '../src/bundle/signature.mjs';

// Ephemeral keys only: no real credential is ever generated by the tests.
export function makeKey(keyId, { notBefore = '2026-01-01T00:00:00Z', notAfter = '2027-12-31T00:00:00Z', revokedAt } = {}) {
  const { privateKey, publicKey } = generateKeyPairSync('ed25519');
  return {
    privateKey,
    entry: { keyId, publicKeyPem: publicKey.export({ type: 'spki', format: 'pem' }), notBefore, notAfter, ...(revokedAt ? { revokedAt } : {}) },
  };
}

export const NOW = Date.parse('2026-11-28T09:00:00Z');
export const COMMIT = 'a'.repeat(40);

export function sampleContent(extra = {}) {
  return {
    schemaVersion: 1,
    stories: [{ slug: 's1', status: 'approved', headline: 'SAMPLE', sources: [{ publisher: 'Example', url: 'https://example.com/a', date: '2026-11-27' }] }],
    classifications: [{ claim: 'SAMPLE', level: 'reported', badgeText: 'Reported by Example', evidence: [{ url: 'https://example.com/e', publisher: 'Example', date: '2026-11-27', type: 'news' }], reviewedBy: 'ed', reviewedAt: '2026-11-27' }],
    controls: { hidden: [{ target: 'item:1', until: '2026-12-31' }] },
    ...extra,
  };
}

export function signedBundle(content, key, { sequence = 10, createdAt = '2026-11-28T08:00:00Z' } = {}) {
  const bundleBytes = Buffer.from(canonicalJSON(content), 'utf8');
  const manifest = buildManifest({ bundleBytes, sequence, sourceCommit: COMMIT, createdAt, keyId: key.entry.keyId });
  return { bundleBytes, manifest, signature: signManifest(manifest, key.privateKey) };
}
